public class RealEstateListing
{
    private int listingNumber;
    private HouseData houseData;
    public RealEstateListing(int num, String address, int sqFt)
    {
        listingNumber = num;
        houseData = new HouseData(address, sqFt);
    }
    public void display()
    {
        System.out.println("#" + listingNumber + " " +
            houseData.streetAddress);
    }
    private class HouseData
    {
        private String streetAddress;
        private int squareFeet;
        public HouseData(String address, int sqFt)
        {
            streetAddress = address;
            squareFeet = sqFt;
        }
    }
}
